(function(root){
 const SUBJECTS=['latin','french','biology','chemistry','physics','english'];
 const day=(at=Date.now())=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(at));
 function read(key){try{return JSON.parse(localStorage.getItem(key)||'{}')}catch{return {}}}
 function withReviewCredits(state){const credits=read('lux-assessment-v1').dailyReviewCredits?.[state.today]||{};return {...state,daily:(state.daily||[]).map(t=>t.id==='mistake-review'&&t.reviewSource==='assessment'&&t.planDate===state.today?{...t,progress:Math.min(t.target,new Set([...(t.completedQuestionIds||[]),...(t.reviewQuestionIds||[]).filter(id=>credits[id])]).size)}:t)}}
 function garden(){const x=read('lux-scholar-garden-v1');return withReviewCredits(x.state||x)}
 function safeHref(value){try{const u=new URL(value,'https://glojournal-cmyk.github.io');return u.origin==='https://glojournal-cmyk.github.io'&&/^\/(study(?:\/|$)|assessment(?:\/|$)|garden(?:\/|$)|play(?:\/|$))/.test(u.pathname)?u.pathname+u.search:null}catch{return null}}
 function navigationHref(value){const href=safeHref(value);if(!href)return null;const u=new URL(href,'https://glojournal-cmyk.github.io');u.searchParams.set('v','20261004-continue4');return u.pathname+u.search}
 function clean(v){try{return JSON.parse(v)}catch{return v}}
 function currentTask(state,href,taskId){if(state.today!==day())return null;const rows=state.daily||[];if(taskId)return rows.find(t=>t.id===taskId)||null;try{const u=new URL(href,'https://glojournal-cmyk.github.io'),p=u.searchParams,id=clean(p.get('task'));if(id)return rows.find(t=>t.id===id)||null;if(clean(p.get('daily'))!=='1')return null;return rows.find(t=>{const v=new URL(t.href,'https://glojournal-cmyk.github.io');return v.pathname.replace(/\/$/,'')===u.pathname.replace(/\/$/,'')&&['mode','topic','year','task'].every(k=>(clean(v.searchParams.get(k))||'')===(clean(p.get(k))||''))})||null}catch{return null}}
 const done=t=>Number(t.progress)>=Number(t.target);
 function completion(state,href,taskId){const task=currentTask(state,href,taskId);if(!task)return null;const rows=(state.daily||[]).filter(t=>safeHref(t.href)),next=rows.find(t=>t.id!==task.id&&!done(t));return {task,done:done(task),completed:rows.filter(done).length,total:rows.length,next:next?{...next,href:navigationHref(next.href)}:null,remaining:Math.max(0,Number(task.target)-Number(task.progress))}}
 function resumeCandidates(state=garden(),at=Date.now()){
  const candidates=[],today=day(at);
  function add(row){const href=navigationHref(row.href);if(!href||!Number.isInteger(row.index)||row.index<0||row.index>=row.total)return;const task=currentTask(state,href,row.dailyTaskId);if(row.daily&&(row.planDate!==today||!task||done(task)))return;candidates.push({...row,href,savedAt:Number(row.savedAt)||0})}
  for(const [key,d] of Object.entries(read('lux-practice-drafts-v1'))){
   if(d?.version!==1||d.ce||at-d.savedAt>=7*86400000||!Array.isArray(d.base)||!d.base.length)continue;
   let parts;try{parts=JSON.parse(key)}catch{continue}const [subject,year,size,topic,dailyId,mode,task,scope,planDate]=parts;if(!SUBJECTS.includes(subject))continue;
   const params=new URLSearchParams({year:String(year),mode:mode||'standard'});if(topic)params.set('topic',topic);if(scope)params.set('scope',scope);if(task)params.set('task',task);const daily=!!d.daily||!!dailyId||!!planDate||!!task;if(daily){params.set('daily','1');params.set('locked','1')}
   const label=subject[0].toUpperCase()+subject.slice(1),title=d.title||label+' · '+(d.base[0]?.topic||'Practice');
   add({href:d.href||`/study/${subject}/practise?${params}`,title,index:d.j,total:d.base.length+(d.rr?.length||0),savedAt:d.savedAt,daily,dailyTaskId:d.dailyTaskId||task||dailyId,planDate:d.planDate||planDate||(daily?day(d.savedAt):null)});
  }
  const bio=read('scholar-biology-cell-practice-v1');if(Array.isArray(bio.ids)&&bio.ids.length)add({href:'/study/biology/practise/?mode=cellstructure',title:'Biology · Cell structure',index:bio.index||0,total:bio.ids.length,savedAt:bio.savedAt||Math.max(0,...Object.values(bio.history||{}).map(x=>Number(x.at)||0))});
  const assessment=read('lux-assessment-v1');
  for(const [id,d] of Object.entries(assessment.drafts||{}))if(d?.version===2&&Array.isArray(d.questions)&&d.questions.length)add({href:'/assessment/?paper='+encodeURIComponent(id),title:d.title||id.split('-').map(s=>s[0]?.toUpperCase()+s.slice(1)).join(' ')+' · Assessment',index:d.index||0,total:d.questions.length,savedAt:d.savedAt||d.started});
  for(const [id,d] of Object.entries(assessment.followups||{}))if(Array.isArray(d.questions)&&d.questions.length)add({href:d.daily?`/assessment/?task=mistake-review&day=${d.planDate}`:'/assessment/?resumeFollowup='+encodeURIComponent(id),title:d.paper||'Assessment corrections',index:d.index||0,total:d.questions.length,savedAt:d.savedAt,daily:!!d.daily,dailyTaskId:d.daily?'mistake-review':null,planDate:d.planDate});
  return candidates.sort((a,b)=>b.savedAt-a.savedAt||a.href.localeCompare(b.href));
 }
 function completionDOM(parent,taskId,state=garden()){const data=completion(state,location.href,taskId);if(!data)return;const box=document.createElement('section');box.setAttribute('aria-label','Daily task progress');box.setAttribute('role','status');box.style.cssText='padding:18px;margin:16px 0;border:1px solid #b8c9b8;border-radius:16px;background:#eef3e9;color:#173e50';const h=document.createElement('h2');h.textContent=data.done?'Counted towards today’s tasks':'Practice saved · daily target still in progress';const p=document.createElement('p');p.textContent=`${data.task.title}: ${Math.min(data.task.progress,data.task.target)}/${data.task.target}. Today: ${data.completed}/${data.total} tasks complete.`+(data.done?'':` ${data.remaining} more required to complete this task.`);box.append(h,p);const progress=document.createElement('progress');progress.setAttribute('aria-label','Today’s completed tasks');progress.value=data.completed;progress.max=data.total;progress.style.cssText='display:block;width:100%;height:12px;margin:12px 0;accent-color:#173e50';box.append(progress);if(!data.done){const retry=document.createElement('a');retry.className='primary';retry.textContent='Continue this task';retry.href=navigationHref(data.task.href);retry.style.marginRight='8px';box.append(retry)}const a=document.createElement('a');a.className='primary';a.style.cssText='display:inline-flex;align-items:center;min-height:44px;padding:10px 18px;border-radius:24px;background:#173e50;color:#fffdf6;text-decoration:none';a.textContent=data.next?'Next task · '+data.next.title:data.done?'Today’s tasks complete · return home':'Return to today’s tasks';a.href=data.next?.href||'/';box.append(a);parent.prepend(box);return box}
 function watchActions(store){let queued=false,signature='',knownDone=new Set((store.getState().daily||[]).filter(done).map(t=>t.id));function update(){queued=false;const state=store.getState(),path=location.pathname.replace(/\/$/,'');const task=state.today===day()&&(state.daily||[]).find(t=>['tend-garden','play-game','pe-session'].includes(t.id)&&done(t)&&((t.id==='tend-garden'&&path==='/garden')||(t.id==='play-game'&&path.startsWith('/play/'))||(t.id==='pe-session'&&path.startsWith('/play/pe-'))));const newlyDone=task&&!knownDone.has(task.id);knownDone=new Set((state.daily||[]).filter(done).map(t=>t.id));const parent=document.querySelector('main'),old=document.querySelector('[data-journey-action]');if(!task||!parent){if(old)old.remove();signature='';return}const data=completion(state,location.href,task.id),nextSignature=JSON.stringify(data);if(old&&signature===nextSignature)return;if(old)old.remove();const box=completionDOM(parent,task.id,state);if(box){box.dataset.journeyAction='true';box.style.scrollMarginTop='88px';signature=nextSignature;if(newlyDone)box.scrollIntoView({block:'start',behavior:'smooth'})}}function schedule(){if(queued)return;queued=true;requestAnimationFrame(update)}store.subscribe(schedule);new MutationObserver(schedule).observe(document.documentElement,{childList:true,subtree:true});window.addEventListener('popstate',schedule);schedule()}
 root.LuxJourney={withReviewCredits,day,safeHref,navigationHref,currentTask,completion,resumeCandidates,garden,completionDOM,watchActions};
})(globalThis);
